TLM.f("Sancti/07-30",{"officium":"S. Abdon et Sennen Martyrum","rule":["vide C3;","Gloria"],"fallback":"Commune/C3","from":{"Introitus":"Commune/C3","Tractus":"Commune/C3"},"sections":{"Introitus":[{"k":"ref","la":"Ps 78:11-12; 78:10"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."},{"k":"ref","la":"Ps 78:1"},{"k":"text","la":"Deus, venérunt gentes in hereditátem tuam: polluérunt templum sanctum tuum: posuérunt Jerúsalem in pomórum custódiam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Intret in conspéctu tuo, Dómine, gémitus compeditórum: redde vicínis nostris séptuplum in sinu eórum: víndica sánguinem Sanctórum tuórum, qui effúsus est."}],"Oratio":[{"k":"text","la":"Deus, qui sanctis tuis Abdon et Sennen ad hanc glóriam veniéndi copiósum munus grátiæ contulísti: da fámulis tuis suorum véniam peccatórum; ut, Sanctórum tuórum intercedéntibus méritis, ab ómnibus mereántur adversitátibus liberáti."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Corínthios"},{"k":"ref","la":"2 Cor 6:4-10"},{"k":"text","la":"Fratres: Exhibeámus nosmetípsos sicut Dei minístros, in multa patiéntia, in tribulatiónibus, in necessitátibus, in angústiis, in plagis, in carcéribus, in seditiónibus, in labóribus, in vigíliis, in jejúniis, in castitáte, in sciéntia, in longanimitáte, in suavitáte, in Spíritu Sancto, in caritáte non ficta, in verbo veritátis, in virtúte Dei, per arma justítiæ a dextris et a sinístris: per glóriam et ignobilitátem: per infámiam et bonam famam: ut seductóres et veráces: sicut qui ignóti et cógniti: quasi moriéntes et ecce, vívimus: ut castigáti et non mortificáti: quasi tristes, semper autem gaudéntes: sicut egéntes, multos autem locupletántes: tamquam nihil habéntes et ómnia possidéntes."}],"Graduale":[{"k":"ref","la":"Exodi 15:11"},{"k":"text","la":"Gloriosus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua. Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos."},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 3:1"},{"k":"text","la":"Justórum ánimæ in manu Dei sunt, et non tanget illos torméntum malítiæ. Allelúja."}],"Tractus":[{"k":"ref","la":"Exod 15:11"},{"k":"text","la":"Gloriósus Deus in Sanctis suis: mirábilis in majestáte, fáciens prodígia."},{"k":"ref","la":"Exod 15:6"},{"k":"text","la":"Déxtera tua, Dómine, glorificáta est in virtúte: déxtera manus tua confrégit inimícos.","mark":"V"},{"k":"ref","la":"Ps 125:5-6"},{"k":"text","la":"Qui séminant in lácrimis, in gáudio metent."},{"k":"text","la":"Eúntes ibant et flébant, mitténtes sémina sua.","mark":"V"},{"k":"text","la":"Veniéntes autem vénient cum exsultatióne, portántes manípulos suos.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:1-12"},{"k":"text","la":"In illo témpore: Videns Jesus turbas, ascéndit in montem, et cum sedísset, accessérunt ad eum discípuli ejus, et apériens os suum, docébat eos, dicens: Beáti páuperes spíritu: quóniam ipsórum est regnum cœlórum. Beáti mites: quóniam ipsi possidébunt terram. Beáti, qui lugent: quóniam ipsi consolabúntur. Beáti, qui esúriunt et sítiunt justítiam: quóniam ipsi saturabúntur. Beáti misericórdes: quóniam ipsi misericórdiam consequántur. Beáti mundo corde: quóniam ipsi Deum vidébunt. Beáti pacífici: quóniam fílii Dei vocabúntur. Beáti, qui persecutiónem patiúntur propter justítiam: quóniam ipsórum est regnum cœlórum. Beáti estis, cum maledíxerint vobis et persecúti vos fúerint, et díxerint omne malum advérsum vos, mentiéntes, propter me: gaudete et exsultáte, quóniam merces vestra copiósa est in cœlis."}],"Offertorium":[{"k":"ref","la":"Ps 67:36"},{"k":"text","la":"Mirábilis Deus in Sanctis suis: Deus Israël, ipse dabit virtútem et fortitúdinem plebi suæ: benedíctus Deus, allelúja."}],"Secreta":[{"k":"text","la":"Hæc hóstia, quǽsumus, Dómine, quam sanctórum Mártyrum tuórum natalítia recenséntes offérimus: et víncula nostræ pravitátis absolvat, et tuæ nobis misericórdiæ dona concíliet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 78:2 & 11"},{"k":"text","la":"Posuérunt mortália servórum tuórum, Dómine, escas volatílibus cœli, carnes Sanctórum tuórum béstiis terræ: secúndum magnitúdinem bráchii tui pósside fílios morte punitórum."}],"Postcommunio":[{"k":"text","la":"Per hujus, Dómine, operationem mystérii, et vitia nostra purgéntur: et, intercedéntibus sanctis Martyribus tuis Abdon et Sennen, justa desidéria compleántur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"5a5b78cf4d99d976":{"t":"<i>Pomolimo se</i>.\nBože, koji si svojim svetima Abdonu i Senenu podijelio bogati dar milosti da dođu do ove slave, daj svojim slugama oproštenje njihovih grijeha, da se zavrijede po zagovoru i zaslugama tvojih svetih izbaviti od svih protivština.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si svetima svojim Abdonu i Sennenu udijelio cbiilje milosti svoje ' da ■uzmognu doći do ove slave, podaj službenicima svojim oproištenje grijeha, da zagovorom zasluga Tvojih svetih budu vrijedni, te ih oslobodiš od svih protivština, po G. n.","knRef":"Kniewald 1942, str. 660–661 (snimka 331) (OCR)"},"a555b3c4944c6e7d":{"t":"Ovaj dar, molimo, Gospodine, koji prikazujemo, slaveći nebeski rođendan svetih tvojih mučenika, neka nas odriješi od veza naše zloće i neka nam isprosi darove tvoga milosrđa.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Ova žrtva, molimo. Gospodine, što je prinosimo slaveći rođeni dan Tvojih mučenika, odriješila i okove naše zloće i isprosila nam darove Tvoga milosrđa, po G. n.","knRef":"Kniewald 1942, str. 584–585 (snimka 293) (OCR)"},"a00a3142d4ac0c5d":{"t":"<i>Pomolimo se</i>.\nPo djelovanju ove tajne neka se, Gospodine, očiste naši grijesi i po zagovoru svetih mučenika tvojih Abdona i Senena ispune pravedne želje.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Djelovanjem se. Gospodine, ovoga otajstva, očistile naiše *opačine i, zagovorom svetih Tvojih mučenika Abdona i Sennena, ispunile pravedne želje, po G. n.","knRef":"Kniewald 1942, str. 660–661 (snimka 331) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Ps 63:3"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."},{"k":"ref","la":"Ps. 63:2"},{"k":"text","la":"Exáudi, Deus, oratiónem meam cum déprecor: a timóre inimíci éripe ánimam meam."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Protexísti me, Deus, a convéntu malignántium, allelúja: a multitúdine operántium iniquitátem, allelúja, allelúja."}]}}});
